+import { Pool } from "pg";
+import * as fs from "fs";
+import * as path from "path";
+
+const pool = new Pool({ connectionString: process.env.DATABASE_URL });
+
+interface Column {
+  name: string;
+  type: string;
+  nullable: boolean;
+}
+
+interface Table {
+  name: string;
+  columns: Column[];
+}
+
+async function getSchema(): Promise<Table[]> {
+  const result = await pool.query(`
+    SELECT
+      t.table_name,
+      c.column_name,
+      c.data_type,
+      c.is_nullable = 'YES' as is_nullable
+    FROM information_schema.tables t
+    JOIN information_schema.columns c ON t.table_name = c.table_name
+    WHERE t.table_schema = 'public'
+    ORDER BY t.table_name, c.ordinal_position
+  `);
+
+  const tables = new Map<string, Table>();
+  for (const row of result.rows) {
+    const table = tables.get(row.table_name) || { name: row.table_name, columns: [] };
+    table.columns.push({
+      name: row.column_name,
+      type: pgTypeToTsType(row.data_type, row.is_nullable),
+      nullable: row.is_nullable,
+    });
+    tables.set(row.table_name, table);
+  }
+  return Array.from(tables.values());
+}
+
+function pgTypeToTsType(pgType: string, nullable: boolean): string {
+  let tsType = "";
+  switch (pgType) {
+    case "integer":
+    case "bigint":
+    case "smallint":
+      tsType = "number";
+      break;
+    case "text":
+    case "character varying":
+    case "character":
+      tsType = "string";
+      break;
+    case "boolean":
+      tsType = "boolean";
+      break;
+    case "timestamp":
+    case "timestamp without time zone":
+    case "timestamp with time zone":
+      tsType = "Date";
+      break;
+    case "date":
+      tsType = "Date";
+      break;
+    default:
+      tsType = "unknown";
+  }
+  return nullable ? `${tsType} | null` : tsType;
+}
+
+function generateTypesFile(tables: Table[]): string {
+  let output = "/* Auto-generated database types. Do not edit manually. */\n\n";
+
+  for (const table of tables) {
+    const interfaceName = pascalCase(table.name);
+    output += `export interface ${interfaceName} {\n`;
+    for (const col of table.columns) {
+      output += `  ${col.name}: ${col.type};\n`;
+    }
+    output += "}\n\n";
+  }
+
+  return output;
+}
+
+function pascalCase(str: string): string {
+  return str
+    .split("_")
+    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
+    .join("");
+}
+
+async function main() {
+  try {
+    const tables = await getSchema();
+    const typesContent = generateTypesFile(tables);
+    const outputPath = path.join(__dirname, "../src/db/types.ts");
+    fs.writeFileSync(outputPath, typesContent, "utf-8");
+    console.log(`Generated types to ${outputPath}`);
+  } catch (err) {
+    console.error("Failed to generate types:", err);
+    process.exit(1);
+  } finally {
+    await pool.end();
+  }
+}
+
+main();
